<?php
declare(strict_types=1);
namespace Qmdb\Modules\Organizations\Interface\Console;
use Qmdb\Modules\Organizations\Application\OrganizationsRegistryReadinessCheck;use Qmdb\Modules\Organizations\Configuration\OrganizationsRegistryConfiguration;use Qmdb\Shared\Console\Command\ConsoleCommand;use Qmdb\Shared\Console\Command\ConsoleCommandName;use Qmdb\Shared\Console\Input\ConsoleInput;use Qmdb\Shared\Console\Output\ConsoleOutput;
final readonly class OrganizationsRegistryVerifyConsoleCommand implements ConsoleCommand { public function __construct(private OrganizationsRegistryConfiguration $configuration,private OrganizationsRegistryReadinessCheck $readiness){} public function name():ConsoleCommandName{return new ConsoleCommandName('organizations:registry:verify');}public function description():string{return 'Verify the tenant-owned Organization and Unit registry foundation.';}public function execute(ConsoleInput $in,ConsoleOutput $out):int{$in->assertOnlyOptions([]);$r=$this->readiness->report();if(!$this->readiness->isReady()){$out->write("Organizations registry verification: FAIL\n");return 1;}$out->write(sprintf("Organizations registry verification: PASS\nMaximum Unit depth: %d\nMaximum Units per Organization: %d\nOrganization count: %d\nUnit count: %d\nInvalid-row count: %d\n",$this->configuration->unitMaximumDepth,$this->configuration->maximumUnits,$r['organizations'],$r['units'],$r['invalid_rows']));return 0;}}
